fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // helper to compute S(k) in a safe wider type
    fn prefix(k: i32) -> i32 {
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }

    let mut result = Vec::with_capacity(queries.len());
    for (l, r) in queries.into_iter() {
        let l = l as i32;
        let r = r as i32;
        // S(r) - S(l-1)
        let ans = prefix(r) - prefix(l - 1);
        result.push(ans as i8);
    }
    result
}

